// Painel · Montar página HTML (única, sem dependências externas, atualiza sozinha a cada 5 s por meta refresh).
// Todo texto vindo de evento passa por esc() antes de entrar no HTML.
const estado = $input.first().json;
const tarefas = Array.isArray(estado.tarefas) ? estado.tarefas : [];
const eventos = Array.isArray(estado.eventos) ? estado.eventos : [];
const c = estado.contadores || {};

const esc = (v) => String(v === undefined || v === null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const ETAPAS = [
  ['jira', 'Jira'], ['plano', 'Plano'], ['aprovado', 'Aprovação'], ['implementacao', 'Implementação'],
  ['qa', 'QA'], ['seguranca', 'Segurança'], ['review', 'Review'], ['commit', 'Commit'],
  ['pr', 'Pull request'], ['registro', 'Registro'], ['concluida', 'Concluída'], ['pausada', 'Pausa'],
];
const ROTULO_ETAPA = Object.fromEntries(ETAPAS);
const STATUS = {
  iniciada: { texto: 'Em andamento', icone: '●', classe: 'agora' },
  concluida: { texto: 'Concluída', icone: '✓', classe: 'fria' },
  falhou: { texto: 'Falhou', icone: '✕', classe: 'alerta' },
  bloqueada: { texto: 'Bloqueada', icone: '⏸', classe: 'alerta' },
};
const st = (s) => STATUS[s] || { texto: s || 'Desconhecido', icone: '○', classe: 'fria' };

const agora = Date.now();
const quando = (iso) => {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '—';
  const s = Math.max(0, Math.round((agora - t) / 1000));
  if (s < 10) return 'agora mesmo';
  if (s < 60) return 'há ' + s + ' s';
  if (s < 3600) return 'há ' + Math.round(s / 60) + ' min';
  if (s < 86400) return 'há ' + Math.round(s / 3600) + ' h';
  return 'há ' + Math.round(s / 86400) + ' d';
};
const hora = (iso) => {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '—';
  return new Date(t).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
};

const cartao = (t) => {
  const s = st(t.status);
  return '<article class="cartao ' + s.classe + '">'
    + '<div class="cartao-topo"><strong class="id">' + esc(t.tarefa) + '</strong>'
    + '<span class="selo ' + s.classe + '"><span aria-hidden="true">' + s.icone + '</span> ' + esc(s.texto) + '</span></div>'
    + '<p class="titulo">' + esc(t.titulo || 'Sem título registrado') + '</p>'
    + '<p class="meta">Agente <span class="agente">' + esc(t.agente) + '</span></p>'
    + '<p class="meta"><time datetime="' + esc(t.atualizado_em) + '">' + esc(quando(t.atualizado_em)) + '</time> · ' + esc(hora(t.atualizado_em)) + '</p>'
    + '</article>';
};

const raias = ETAPAS.map(([chave, rotulo]) => {
  let lista = tarefas.filter((t) => t.etapa === chave);
  const total = lista.length;
  if (chave === 'concluida') lista = lista.slice(0, 8);
  const corpo = lista.length ? lista.map(cartao).join('') : '<p class="vazio">Nada por aqui</p>';
  return '<section class="raia" aria-label="Etapa ' + esc(rotulo) + '"><h3>' + esc(rotulo) + '<span class="n">' + total + '</span></h3>' + corpo + '</section>';
}).join('');

const atencao = tarefas.filter((t) => t.status === 'falhou' || t.status === 'bloqueada');
const blocoAtencao = atencao.length
  ? '<section class="atencao" aria-labelledby="h-atencao"><h2 id="h-atencao">Precisa de atenção</h2><div class="grade">' + atencao.map(cartao).join('') + '</div></section>'
  : '';

const linha = eventos.length
  ? eventos.slice(0, 20).map((e) => {
    const s = st(e.status);
    return '<li class="evento ' + s.classe + '"><span class="ponto" aria-hidden="true"></span><div>'
      + '<p class="evento-t"><strong>' + esc(e.tarefa) + '</strong> · ' + esc(ROTULO_ETAPA[e.etapa] || e.etapa) + ' · ' + esc(s.texto) + '</p>'
      + '<p class="meta">' + esc(e.agente) + ' · <time datetime="' + esc(e.ts) + '">' + esc(hora(e.ts)) + '</time></p>'
      + (e.resumo ? '<p class="resumo">' + esc(e.resumo) + '</p>' : '')
      + '</div></li>';
  }).join('')
  : '<li class="vazio">Nenhum evento recebido ainda. Envie um POST para /webhook/lume-dev-evento.</li>';

const contador = (rotulo, valor, classe) => '<div class="contador ' + (classe || '') + '"><span class="valor">' + esc(valor === undefined ? 0 : valor) + '</span><span class="rotulo">' + esc(rotulo) + '</span></div>';

const css = `
:root{color-scheme:dark;--bg:#050506;--surface:#0C0C0F;--surface-2:#17171B;--linha:#232328;--texto:#FFFFFF;--texto-2:#A6A6AF;--laranja:#FF8A00;--brasa:#FF4F1F;--violeta:#5B16F0;--violeta-claro:#B9A3FF;--erro:#FF7A72;--r1:16px;--r2:12px;--r3:8px;--luz:linear-gradient(90deg,var(--laranja),var(--brasa));--sombra:0 1px 2px rgba(0,0,0,.5),0 8px 24px rgba(0,0,0,.35)}
*{box-sizing:border-box}
html{background:var(--bg)}
body{margin:0;min-height:100vh;background:var(--bg);color:var(--texto);font:15px/1.5 Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;position:relative;overflow-x:hidden}
body::before{content:"";position:fixed;inset:0;pointer-events:none;background:radial-gradient(60vw 50vh at 12% -5%,rgba(91,22,240,.20),transparent 70%),radial-gradient(50vw 45vh at 95% 105%,rgba(255,110,20,.10),transparent 70%)}
.topo{position:relative;border-bottom:1px solid var(--linha);background:rgba(12,12,15,.85)}
.topo::before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:var(--luz);opacity:.9}
.topo-in,main,footer{position:relative;max-width:1400px;margin:0 auto;padding:16px}
.topo-in{display:flex;flex-wrap:wrap;gap:8px 24px;align-items:baseline;justify-content:space-between}
h1{margin:0;font-size:20px;font-weight:650;letter-spacing:-.01em}
.sub{margin:0;color:var(--texto-2);font-size:13px}
h2{font-size:14px;margin:0 0 12px;font-weight:600;color:var(--texto-2);text-transform:uppercase;letter-spacing:.06em}
h3{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px;font-size:14px;font-weight:600}
.n{min-width:24px;text-align:center;padding:0 8px;border-radius:999px;background:var(--surface-2);color:var(--texto-2);font-size:12px;line-height:22px}
.contadores{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:24px}
.contador{background:var(--surface);border:1px solid var(--linha);border-top-color:rgba(255,255,255,.10);border-radius:var(--r1);padding:16px;box-shadow:var(--sombra);display:flex;flex-direction:column;gap:4px}
.contador .valor{font-size:28px;font-weight:700;line-height:1.1}
.contador .rotulo{font-size:13px;color:var(--texto-2)}
.contador.agora .valor{background:var(--luz);-webkit-background-clip:text;background-clip:text;color:transparent}
.contador.fria .valor{color:var(--violeta-claro)}
.contador.alerta .valor{color:var(--erro)}
.raias{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(232px,1fr);gap:12px;overflow-x:auto;padding-bottom:12px;margin-bottom:24px;scrollbar-color:var(--linha) transparent}
.raia{background:var(--surface);border:1px solid var(--linha);border-radius:var(--r1);padding:12px;min-height:120px;display:flex;flex-direction:column;gap:8px}
.raia h3{margin-bottom:4px}
.cartao{background:var(--surface-2);border:1px solid var(--linha);border-top-color:rgba(255,255,255,.10);border-radius:var(--r2);padding:12px;position:relative;box-shadow:var(--sombra)}
.cartao p{margin:0}
.cartao-topo{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:4px}
.id{font-size:13px}
.titulo{font-size:14px;margin:4px 0 8px;overflow-wrap:anywhere}
.meta{font-size:12px;color:var(--texto-2);overflow-wrap:anywhere}
.agente{color:var(--texto)}
.selo{display:inline-flex;gap:4px;align-items:center;white-space:nowrap;font-size:12px;padding:2px 8px;border-radius:var(--r3);border:1px solid var(--linha)}
.selo.agora{color:#FFB366;border-color:rgba(255,138,0,.5)}
.selo.fria{color:var(--violeta-claro);border-color:rgba(91,22,240,.55)}
.selo.alerta{color:var(--erro);border-color:rgba(255,122,114,.5)}
.cartao.agora{border-color:rgba(255,138,0,.45);box-shadow:var(--sombra),0 0 24px rgba(255,100,20,.22);animation:respirar 6s ease-in-out infinite}
.cartao.agora::before{content:"";position:absolute;left:12px;right:12px;top:-1px;height:2px;border-radius:2px;background:var(--luz)}
.cartao.fria{border-left:3px solid var(--violeta)}
.cartao.alerta{border-style:dashed;border-color:rgba(255,122,114,.55)}
@keyframes respirar{0%,100%{box-shadow:var(--sombra),0 0 14px rgba(255,100,20,.14)}50%{box-shadow:var(--sombra),0 0 30px rgba(255,100,20,.34)}}
.vazio{margin:0;color:var(--texto-2);font-size:13px;padding:8px 0}
.atencao{margin-bottom:24px}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px}
.linha-tempo{background:var(--surface);border:1px solid var(--linha);border-radius:var(--r1);padding:16px;box-shadow:var(--sombra)}
.linha-tempo ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}
.evento{display:flex;gap:12px}
.evento .ponto{flex:none;width:10px;height:10px;margin-top:6px;border-radius:50%;background:var(--violeta)}
.evento.agora .ponto{background:var(--luz);box-shadow:0 0 10px rgba(255,100,20,.6)}
.evento.alerta .ponto{background:var(--erro)}
.evento-t{margin:0;font-size:14px}
.evento .meta{margin:0}
.resumo{margin:2px 0 0;font-size:13px;color:var(--texto-2);overflow-wrap:anywhere}
footer{color:var(--texto-2);font-size:12px}
@media (max-width:720px){.raias{grid-auto-flow:row;grid-auto-columns:auto;overflow-x:visible}.contador .valor{font-size:24px}}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
`;

const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<meta http-equiv="refresh" content="5">'
  + '<title>Lume · Painel de desenvolvimento</title><style>' + css + '</style></head><body>'
  + '<header class="topo"><div class="topo-in"><h1>Lume · Painel de desenvolvimento</h1>'
  + '<p class="sub">Atualizado às ' + esc(hora(estado.gerado_em)) + ' · atualiza sozinho a cada 5 s</p></div></header>'
  + '<main>'
  + '<section class="contadores" aria-label="Contadores">'
  + contador('Em andamento', c.em_andamento, 'agora') + contador('Concluídas', c.concluidas, 'fria')
  + contador('Bloqueadas ou com falha', c.bloqueadas, c.bloqueadas ? 'alerta' : '') + contador('Tarefas acompanhadas', c.tarefas)
  + contador('Eventos registrados', c.eventos) + '</section>'
  + blocoAtencao
  + '<h2>Raias por etapa</h2><div class="raias" role="list">' + raias.replace(/<section class="raia"/g, '<section role="listitem" class="raia"') + '</div>'
  + '<section class="linha-tempo" aria-labelledby="h-linha"><h2 id="h-linha">Linha do tempo recente</h2><ol>' + linha + '</ol></section>'
  + '</main><footer>O que está em laranja acontece agora; o violeta já esfriou ou terminou. Eventos descartados por inválidos: ' + esc(c.descartados === undefined ? 0 : c.descartados) + '.</footer>'
  + '</body></html>';

return [{ json: { html } }];
